begin;
-- Fresh local development fixture required: npm run db:reset:dev.
-- These helpers run as the current test role, never as SECURITY DEFINER.
create schema test;
create function test.ok(p_condition boolean, p_description text) returns text
language plpgsql as $$
begin
  if p_condition is distinct from true then raise exception 'Assertion failed: %', p_description; end if;
  return 'ok - ' || p_description;
end;
$$;
create function test.throws(p_sql text, p_state text, p_description text) returns text
language plpgsql as $$
declare v_state text;
begin
  begin execute p_sql; exception when others then v_state := sqlstate; end;
  if v_state is distinct from p_state then
    raise exception 'Assertion failed: % (expected SQLSTATE %, received %)', p_description, p_state, coalesce(v_state, 'no error');
  end if;
  return 'ok - ' || p_description;
end;
$$;
grant usage on schema test to anon, authenticated;
grant execute on function test.ok(boolean,text), test.throws(text,text,text) to anon, authenticated;

select 'TAP version 13';
select test.ok((select count(*) = 7 from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity), 'all seven exposed tables have RLS enabled');
select test.ok((select count(*) = 5 from public.profiles), 'development seed replay does not duplicate profiles');
select test.ok((select count(*) = 2 from public.rides), 'development seed replay does not duplicate rides');
select test.ok((select count(*) = 7 from information_schema.columns where table_schema = 'public' and column_name = 'id' and data_type = 'uuid'), 'all application primary identifiers are UUIDs');
select test.ok((select data_type = 'numeric' from information_schema.columns where table_schema = 'public' and table_name = 'bids' and column_name = 'amount'), 'money uses NUMERIC');
select test.ok((select created_at is not null and updated_at is not null from public.rides where id = '40000000-0000-4000-8000-000000000001'), 'timestamps are generated by the database');
select test.ok(not has_table_privilege('authenticated','public.profiles','UPDATE'), 'ordinary clients have no direct profile update privilege');
select test.ok(not has_function_privilege('anon','public.accept_bid(uuid)','EXECUTE'), 'anonymous callers cannot execute assignment');
select test.ok(not has_function_privilege('authenticated','private.handle_new_user()','EXECUTE'), 'signup trigger is not client executable');
select test.ok((select bool_and(p.proconfig @> array['search_path=""']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef), 'every definer function pins an empty search path');

select test.throws($q$insert into public.profiles(id,full_name) values ('99999999-0000-4000-8000-000000000001','Orphan Profile')$q$, '23503', 'profile must reference an auth user');
select test.throws($q$insert into public.bids(ride_id,biker_id,amount) values ('99999999-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',100)$q$, '23503', 'bid must reference an existing ride');
select test.throws($q$insert into public.biker_profiles(id) values ('10000000-0000-4000-8000-000000000001')$q$, '23514', 'customer cannot have a biker profile');
select test.throws($q$update public.profiles set full_name=null where id='10000000-0000-4000-8000-000000000001'$q$, '23502', 'full name is not nullable');
select test.throws($q$update public.rides set expected_fare=-1 where id='40000000-0000-4000-8000-000000000001'$q$, '23514', 'negative fare is rejected');
select test.throws($q$update public.rides set expected_fare='NaN'::numeric where id='40000000-0000-4000-8000-000000000001'$q$, '23514', 'NaN fare is rejected');
select test.throws($q$update public.rides set pickup_latitude=91 where id='40000000-0000-4000-8000-000000000001'$q$, '23514', 'invalid latitude is rejected');
select test.throws($q$update public.rides set status='completed' where id='40000000-0000-4000-8000-000000000001'$q$, '23514', 'completed ride requires assignment and timestamps');
select test.throws($q$insert into public.bids(ride_id,biker_id,amount) values ('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',120)$q$, '23505', 'duplicate biker bid is rejected by UNIQUE');
select test.throws($q$delete from auth.users where id='10000000-0000-4000-8000-000000000001'$q$, '23001', 'deleting an auth user cannot orphan ride history');
select test.throws($q$insert into public.complaints(reporter_id,subject,description) values ('99999999-0000-4000-8000-000000000001','Orphan reporter','Invalid reporter must be rejected.')$q$, '23503', 'complaint must reference an existing reporter');

insert into auth.users(id,email,raw_user_meta_data) values ('80000000-0000-4000-8000-000000000001','escalation@example.invalid','{"full_name":"Escalation Attempt","role":"admin","account_status":"suspended"}');
select test.ok((select role='customer' and account_status='active' from public.profiles where id='80000000-0000-4000-8000-000000000001'), 'signup metadata cannot grant admin or choose account status');
update auth.users set raw_user_meta_data='{"role":"admin"}' where id='10000000-0000-4000-8000-000000000001';
select test.ok((select role='customer' from public.profiles where id='10000000-0000-4000-8000-000000000001'), 'later metadata edits cannot change profile role');

set local role anon;
set local "request.jwt.claim.sub" = '';
select test.ok(public.backend_health()->>'application'='RideShare Pro', 'anonymous health probe exposes only application metadata');
select test.throws('select * from public.profiles', '42501', 'anonymous cannot read profiles');
select test.throws('select * from public.biker_profiles', '42501', 'anonymous cannot read biker profiles');
select test.throws('select * from public.rides', '42501', 'anonymous cannot read rides');
select test.throws('select * from public.bids', '42501', 'anonymous cannot read bids');
select test.throws('select * from public.ratings', '42501', 'anonymous cannot read ratings');
select test.throws('select * from public.complaints', '42501', 'anonymous cannot read complaints');
select test.throws('select * from public.admin_audit_logs', '42501', 'anonymous cannot read audit logs');
select test.throws($q$select public.accept_bid('60000000-0000-4000-8000-000000000001')$q$, '42501', 'anonymous assignment is denied');

reset role;
set local role authenticated;
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000001';
select test.ok(current_user='authenticated', 'authorization tests actually use the nonprivileged authenticated role');
select test.ok((select count(*)=1 from public.profiles), 'customer sees only own private profile');
select test.ok((select count(*)=1 from public.rides), 'customer sees only own ride');
select test.ok((select count(*)=2 from public.bids), 'customer sees bids on own ride');
select test.ok((select count(*)=1 from public.complaints), 'reporter sees own complaint');
select test.ok((select count(*)=0 from public.admin_audit_logs), 'customer sees no admin logs');
select test.ok((select count(*)=2 from public.get_bidder_summaries('40000000-0000-4000-8000-000000000001')), 'customer can read safe bidder summaries');
select test.throws($q$select * from public.get_bidder_summaries('40000000-0000-4000-8000-000000000002')$q$, '42501', 'customer cannot inspect another ride bidder list');
select test.throws($q$update public.profiles set role='admin' where id=auth.uid()$q$, '42501', 'client cannot promote own role');
select test.throws($q$update public.profiles set account_status='active' where id=auth.uid()$q$, '42501', 'client cannot change own account status');
select test.throws($q$update public.rides set customer_id='10000000-0000-4000-8000-000000000002'$q$, '42501', 'client cannot change ride ownership');
select test.throws($q$update public.rides set status='completed'$q$, '42501', 'client cannot bypass status transition RPC');
select test.throws($q$select public.admin_set_account_status('20000000-0000-4000-8000-000000000001','suspended')$q$, '42501', 'customer cannot invoke admin business operation');
select test.throws($q$select public.submit_bid('40000000-0000-4000-8000-000000000001',100)$q$, '42501', 'customer cannot bid');
select test.throws($q$select public.rate_ride('40000000-0000-4000-8000-000000000001',5,null)$q$, '23514', 'open ride cannot be rated');
select test.throws($q$select public.submit_complaint('Unrelated ride','This is not my ride complaint.','40000000-0000-4000-8000-000000000002')$q$, '42501', 'complaint cannot refer to an unrelated ride');
select test.ok((public.update_my_profile('Customer Renamed','01700000001','undisclosed')).role='customer', 'profile RPC changes only permitted fields');
select test.ok(public.post_ride('50000000-0000-4000-8000-000000000001','Campus Gate','Library',23.75,90.39,23.76,90.4,2100,600,100)='40000000-0000-4000-8000-000000000001', 'ride submission retry returns the existing ID');
select test.throws($q$select public.post_ride('90000000-0000-4000-8000-000000000001','Campus Gate','Library',23.75,90.39,23.76,90.4,2100,600,100)$q$, '23505', 'customer cannot create a second active ride');

set local "request.jwt.claim.sub" = '20000000-0000-4000-8000-000000000001';
select test.ok((select count(*)=2 from public.rides), 'available biker can browse open requests');
select test.ok((select count(*)=1 from public.profiles), 'biker cannot read customer or competitor private profiles');
select test.ok((select count(*)=1 from public.bids), 'biker cannot read competing bids');
select test.ok((select count(*)=0 from public.complaints), 'biker cannot read another reporter complaint');
select test.ok((public.set_biker_availability(false)).is_online=false, 'biker can go offline');
select test.ok((select count(*)=0 from public.rides), 'offline biker cannot browse open requests');
select test.throws($q$select public.submit_bid('40000000-0000-4000-8000-000000000001',115)$q$, '42501', 'offline biker cannot submit a bid');
select test.ok((public.set_biker_availability(true)).is_online, 'biker can go online with a complete vehicle profile');
select test.ok((public.update_my_motorcycle('Updated Test Motorcycle','dev-one')).plate_number='DEV-ONE', 'motorcycle RPC normalizes the own vehicle plate');
select test.throws($q$select public.update_my_motorcycle('Test Motorcycle','DEV-TWO')$q$, '23505', 'motorcycle plate must be unique');
select test.ok(public.submit_bid('40000000-0000-4000-8000-000000000001',115)='60000000-0000-4000-8000-000000000001', 'updating a pending bid preserves one unique record');
select test.ok((select amount=115 from public.bids where id='60000000-0000-4000-8000-000000000001'), 'pending bid amount updated');
select test.throws($q$select public.accept_bid('60000000-0000-4000-8000-000000000001')$q$, '42501', 'biker cannot select own bid');
select test.ok(public.submit_bid('40000000-0000-4000-8000-000000000002',140) is not null, 'biker can bid on another open request');

set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000002';
select test.throws($q$select public.accept_bid('60000000-0000-4000-8000-000000000001')$q$, '42501', 'another customer cannot accept the bid');
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000001';
select test.ok(public.accept_bid('60000000-0000-4000-8000-000000000001')='40000000-0000-4000-8000-000000000001', 'ride assignment succeeds for the owner');
select test.ok((select biker_id='20000000-0000-4000-8000-000000000001' and agreed_fare=115 and status='assigned' from public.rides where id='40000000-0000-4000-8000-000000000001'), 'assignment stores selected biker, status, and accepted NUMERIC fare');
select test.ok((select status='rejected' from public.bids where id='60000000-0000-4000-8000-000000000002'), 'competing bid is rejected atomically');
select test.ok(public.accept_bid('60000000-0000-4000-8000-000000000001')='40000000-0000-4000-8000-000000000001', 'same assignment retry is idempotent');
select test.throws($q$select public.accept_bid('60000000-0000-4000-8000-000000000002')$q$, '23514', 'ride cannot be assigned a second biker');
select test.throws($q$select public.transition_ride('40000000-0000-4000-8000-000000000001','in_progress')$q$, '23514', 'customer cannot start the ride');

set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000002';
select test.throws($q$select public.accept_bid((select id from public.bids where ride_id='40000000-0000-4000-8000-000000000002'))$q$, '23514', 'busy biker cannot be assigned to another ride');
set local "request.jwt.claim.sub" = '20000000-0000-4000-8000-000000000002';
select test.throws($q$select public.transition_ride('40000000-0000-4000-8000-000000000001','in_progress')$q$, '42501', 'unassigned biker cannot start a ride');
set local "request.jwt.claim.sub" = '20000000-0000-4000-8000-000000000001';
select test.throws($q$select public.set_biker_availability(true)$q$, '23514', 'assigned biker cannot become available for another assignment');
select test.throws($q$select public.transition_ride('40000000-0000-4000-8000-000000000001','completed')$q$, '23514', 'ride cannot skip the in-progress state');
select test.ok(public.transition_ride('40000000-0000-4000-8000-000000000001','in_progress') is not null, 'assigned biker can start the ride');
select test.ok(public.transition_ride('40000000-0000-4000-8000-000000000001','completed') is not null, 'assigned biker can complete the ride');

set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000002';
select test.throws($q$select public.rate_ride('40000000-0000-4000-8000-000000000001',5,null)$q$, '42501', 'another customer cannot rate the completed ride');
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000001';
select test.throws($q$select public.rate_ride('40000000-0000-4000-8000-000000000001',6,null)$q$, '23514', 'rating score range is enforced');
select test.ok(public.rate_ride('40000000-0000-4000-8000-000000000001',5,'Synthetic test feedback') is not null, 'customer can rate own completed ride');
select test.throws($q$select public.rate_ride('40000000-0000-4000-8000-000000000001',4,null)$q$, '23505', 'duplicate rating is rejected');

reset role;
select test.throws($q$insert into public.ratings(ride_id,customer_id,biker_id,score) values ('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001',5)$q$, '23514', 'relationship trigger rejects forged rating ownership even for trusted SQL');
select test.throws($q$update public.rides set customer_id='10000000-0000-4000-8000-000000000002' where id='40000000-0000-4000-8000-000000000001'$q$, '23503', 'rating composite FK prevents later ownership drift');
set constraints all immediate;
select test.throws($q$update public.rides set accepted_bid_id='60000000-0000-4000-8000-000000000002' where id='40000000-0000-4000-8000-000000000001'$q$, '23503', 'accepted bid composite FK rejects mismatched biker or fare');

set local role authenticated;
set local "request.jwt.claim.sub" = '30000000-0000-4000-8000-000000000001';
select test.ok((select count(*)=6 from public.profiles), 'active administrator can inspect account profiles');
select test.ok((select count(*)=2 from public.rides), 'administrator can inspect all rides');
select test.ok((select count(*)=1 from public.complaints), 'administrator can inspect complaints');
do $setup$ begin perform public.admin_review_complaint('70000000-0000-4000-8000-000000000001','resolved','Development resolution note'); end $setup$;
select test.ok((select status='resolved' and handled_by=auth.uid() and resolved_at is not null from public.complaints where id='70000000-0000-4000-8000-000000000001'), 'admin resolution records handler and timestamp');
select test.ok((select count(*)=1 from public.admin_audit_logs where action='complaint_reviewed'), 'complaint review creates an audit entry');
do $setup$ begin perform public.admin_set_account_status('20000000-0000-4000-8000-000000000001','suspended'); end $setup$;
select test.ok((select account_status='suspended' from public.profiles where id='20000000-0000-4000-8000-000000000001'), 'administrator can suspend a biker');
select test.ok((select count(*)=1 from public.admin_audit_logs where action='account_status_changed'), 'account status update creates an audit entry');
select test.throws($q$select public.admin_set_account_status('30000000-0000-4000-8000-000000000001','suspended')$q$, '42501', 'admin management RPC cannot disable administrator accounts');
do $setup$ begin perform public.transition_ride('40000000-0000-4000-8000-000000000002','cancelled'); end $setup$;
select test.ok((select status='cancelled' from public.rides where id='40000000-0000-4000-8000-000000000002'), 'administrator can cancel an open ride');

set local "request.jwt.claim.sub" = '20000000-0000-4000-8000-000000000001';
select test.ok((select count(*)=1 from public.profiles), 'suspended user can inspect own account status only');
select test.ok((select count(*)=0 from public.rides), 'suspended biker cannot read ride records');
select test.throws($q$select public.set_biker_availability(true)$q$, '42501', 'suspended biker cannot become available');
select test.throws($q$select public.update_my_profile('Suspended Name','01700000001','undisclosed')$q$, '42501', 'suspended user cannot mutate own profile');
select test.throws($q$select public.admin_set_account_status(auth.uid(),'active')$q$, '42501', 'suspended user cannot reactivate own account');

-- Defense in depth: an accidental table grant still cannot bypass missing write policies.
reset role;
grant update, insert on public.profiles to authenticated;
set local role authenticated;
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000001';
with changed as (update public.profiles set role='admin' where id=auth.uid() returning id)
select test.ok(count(*)=0, 'RLS still blocks role edits if UPDATE is accidentally granted') from changed;
select test.throws($q$insert into public.profiles(id,full_name) values ('99999999-0000-4000-8000-000000000002','Forged Profile')$q$, '42501', 'RLS still blocks inserts if INSERT is accidentally granted');

-- Plan is emitted at the end, as permitted by TAP. All test changes roll back.
select '1..101';
rollback;
